# Replays traces of the Python BayesRiskController (elixir/controller_golden.json,
# generated by scripts/gen_elixir_controller_golden.py) through PacingController.
# Run: make -C elixir test
ExUnit.start()

defmodule PacingControllerTest do
  use ExUnit.Case, async: true

  @golden Path.join(__DIR__, "controller_golden.json") |> File.read!() |> JSON.decode!()
  @cases @golden["cases"]
  # p is found by a 30-step bisection; a last-digit difference in a tail can move
  # one late bisection step, i.e. p by about p_hi / 2^30
  @p_tol 1.0e-8

  defp controller(opts, extra \\ []) do
    opts
    |> Enum.map(fn {k, v} -> {String.to_existing_atom(k), v} end)
    |> Keyword.merge(extra)
    |> PacingController.new()
  end

  defp close?(got, want), do: abs(got - want) <= @p_tol * max(1.0, abs(want))

  for %{"name" => name} = golden <- @cases do
    @golden_case golden

    test "decide/5 reproduces Python: #{name}" do
      g = @golden_case

      c =
        Enum.reduce(g["steps"], controller(g["opts"]), fn [t, s, e, w, want_p, want_sent], c ->
          {p, sent?, c} = PacingController.decide(c, t, s, e, w)

          assert close?(p, want_p), "t = #{t}: p = #{p}, Python #{want_p}"
          assert sent? == (want_sent == 1), "t = #{t}: send? = #{sent?}"
          c
        end)

      assert abs(c.risk_used - g["risk_used"]) <= 1.0e-9
      assert c.broadcasts == g["broadcasts"]
      assert c.risk_used <= g["opts"]["eps"]
    end

    test "step/2 tracks exposure like the simulator: #{name}" do
      g = @golden_case

      Enum.reduce(g["steps"], controller(g["opts"]), fn [t, s, e, w, want_p, _], c ->
        assert abs(c.observed_exposure - e) <= 1.0e-9, "t = #{t}: E"
        assert abs(Enum.sum(c.in_flight) * c.step - w) <= 1.0e-9, "t = #{t}: W"
        {p, _sent?, c} = PacingController.step(c, s)
        assert close?(p, want_p), "t = #{t}: p = #{p}, Python #{want_p}"
        c
      end)
    end
  end

  @base [budget: 5000, horizon: 3600, delay: 30, step: 5, prior_mean: 100, eps: 1.0e-3]

  test "stops when the visible spend has reached the budget" do
    {p, _, _} = PacingController.decide(PacingController.new(@base), 600.0, 5000, 60.0, 0.0)
    assert p == 0.0
  end

  test "an empty budget in flight gives p = 0, a full one at the start gives the even pace" do
    c = PacingController.new(@base)
    {p, _, _} = PacingController.decide(c, 0.0, 0, 0.0, 0.0)
    assert_in_delta p, 5000 / (100 * 3600), 1.0e-12
  end

  test "budget and spend in units of c give the same p as counting spends" do
    a = PacingController.new(@base)
    b = PacingController.new(Keyword.merge(@base, budget: 12_500, unit_cost: 2.5))
    {pa, _, _} = PacingController.decide(a, 1800.0, 2450, 24.5, 0.42)
    {pb, _, _} = PacingController.decide(b, 1800.0, 2450 * 2.5, 24.5, 0.42)
    assert pa == pb
  end

  test "the NIF math gives the same decisions" do
    if Code.ensure_loaded?(PacingMathNif) do
      g = hd(@cases)

      for [t, s, e, w, _, _] <- Enum.take_every(g["steps"], 37) do
        {pa, _, _} = PacingController.decide(controller(g["opts"]), t, s, e, w)
        {pb, _, _} = PacingController.decide(controller(g["opts"], math: PacingMathNif), t, s, e, w)
        assert close?(pa, pb)
      end
    end
  end
end
